using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using Microsoft.Extensions.Configuration;
using MigraDoc.DocumentObjectModel;
using MigraDoc.DocumentObjectModel.Tables;
using MigraDoc.Rendering;
using PdfSharp.Fonts;
using Qms.Application.Trainings;
using Qms.Contracts.Trainings;
namespace Qms.Infrastructure.Trainings;

public sealed class TrainingFinalReportService(IConfiguration configuration) : ITrainingFinalReportService
{
    private const string FontFamily = "QmsDejaVuSans"; private static readonly Lock FontLock = new();
    public async Task<TrainingFinalReportFile> EnsureGeneratedAsync(TrainingDetailsResponse details, CancellationToken ct) { if (details.Record.Status != "Completed") throw new InvalidOperationException("Nihai PDF yalnızca tamamlanmış eğitim kayıtları için üretilebilir."); var root = configuration["FileStorage:RootPath"] ?? Path.Combine(AppContext.BaseDirectory, "qms-files"); var dir = Path.Combine(root, "trainings", details.Record.Id.ToString("N")); Directory.CreateDirectory(dir); var safe = string.Concat(details.Record.RecordNumber.Select(c => char.IsLetterOrDigit(c) || c is '-' or '_' ? c : '_')); var name = $"{safe}-nihai-egitim-v{details.Record.Version}.pdf"; var path = Path.Combine(dir, name); var hashPath = path + ".sha256"; var reportIsNew = !File.Exists(path); if (reportIsNew) { EnsureFont(); var bytes = Build(details, SnapshotHash(details)); try { await File.WriteAllBytesAsync(path, bytes, ct); } catch (IOException) when (File.Exists(path)) { } var hash = Convert.ToHexStringLower(SHA256.HashData(await File.ReadAllBytesAsync(path, ct))); try { await File.WriteAllTextAsync(hashPath, hash, Encoding.ASCII, ct); } catch (IOException) when (File.Exists(hashPath)) { } } var content = await File.ReadAllBytesAsync(path, ct); var actual = Convert.ToHexStringLower(SHA256.HashData(content)); var expected = (await File.ReadAllTextAsync(hashPath, ct)).Trim(); if (!CryptographicOperations.FixedTimeEquals(Encoding.ASCII.GetBytes(actual), Encoding.ASCII.GetBytes(expected))) throw new InvalidOperationException("Nihai eğitim PDF bütünlük doğrulamasını geçemedi."); await Qms.Infrastructure.Integrity.FinalReportIntegrity.SealNewOrVerifyAsync(configuration, path, actual, reportIsNew); return new(content, name, actual); }
    private static byte[] Build(TrainingDetailsResponse d, string snapshotHash) { var r = d.Record; var doc = new Document { Info = { Title = $"{r.RecordNumber} Nihai Eğitim Kaydı", Author = "QMS" } }; doc.Styles["Normal"]!.Font.Name = FontFamily; doc.Styles["Normal"]!.Font.Size = 9; var s = doc.AddSection(); s.PageSetup.PageFormat = PageFormat.A4; s.PageSetup.TopMargin = Unit.FromCentimeter(1.5); s.PageSetup.BottomMargin = Unit.FromCentimeter(1.6); s.PageSetup.LeftMargin = s.PageSetup.RightMargin = Unit.FromCentimeter(1.55); var brand = s.AddParagraph("QMS  |  KALİTE YÖNETİM SİSTEMİ"); brand.Format.Font.Bold = true; brand.Format.Font.Color = Color.Parse("#0F7773"); var title = s.AddParagraph(r.CourseTitle); title.Format.Font.Size = 20; title.Format.Font.Bold = true; title.Format.Font.Color = Color.Parse("#0F5F61"); s.AddParagraph($"{r.RecordNumber} | M.05 Eğitim ve Yeterlilik | Kayıt sürümü {r.Version} | NİHAİ - TAMAMLANDI"); Heading(s, "1. Eğitim ve katılımcı özeti"); Grid(s, ["Eğitim kodu", r.CourseCode, "Katılımcı", r.EmployeeName, "Pozisyon", r.Position, "Kaynak doküman", r.DocumentCode is null ? "Bağımsız eğitim" : $"{r.DocumentCode} v{r.DocumentRevision}", "Değerlendirme", r.AssessmentMode, "Sunum yöntemi", r.DeliveryMethod, "Hedef", F(r.DueAtUtc), "Tamamlanma", F(r.CompletedAtUtc), "Geçerlilik sonu", F(r.ExpiresAtUtc)]); Heading(s, "2. Yeterlilik koşulları"); Grid(s, ["Geçme puanı", $"%{r.PassingScore}", "Azami deneme", r.MaxAttempts.ToString(), "Geçerlilik", $"{r.ValidityMonths} ay", "Kritik yeterlilik", r.IsCriticalQualification ? "Evet" : "Hayır", "Oturum", r.SessionCode ?? "-", "Eğitmen", r.Trainer ?? "-"]); Block(s, "Okuma ve anlama beyanı", r.AcknowledgementMeaning is null ? "Gerekli değil / bulunmuyor" : $"{r.AcknowledgementMeaning}\n{F(r.AcknowledgedAtUtc)}"); Heading(s, "3. Değerlendirme denemeleri"); var attempts = Table(s, ["Deneme", "Puan / pratik", "Sonuç", "Kanıt / değerlendirici / tarih"]); foreach (var x in d.Attempts.OrderBy(x => x.AttemptNumber)) Row(attempts, x.AttemptNumber.ToString(), $"%{x.Score} / {(x.PracticalPassed ? "Uygun" : "Uygun değil")}", x.Passed ? "Başarılı" : "Başarısız", $"{x.Evidence}\n{x.Evaluator}\n{F(x.AssessedAtUtc)}"); Block(s, "Eğitmen onay notu", r.TrainerApprovalNote ?? "-"); Heading(s, "4. Elektronik imzalar"); var signs = Table(s, ["Anlam", "İmzalayan", "Tarih / sürüm", "İçerik hash"]); foreach (var x in d.Signatures.OrderBy(x => x.SignedAtUtc)) Row(signs, x.Meaning, x.SignerName, $"{F(x.SignedAtUtc)} / v{x.RecordVersion}", x.ContentHash[..Math.Min(16, x.ContentHash.Length)] + "..."); Heading(s, "5. Denetim izi"); var audit = Table(s, ["Tarih", "Olay", "Kullanıcı", "Sürüm"]); foreach (var x in d.AuditTrail.OrderBy(x => x.OccurredAtUtc)) Row(audit, F(x.OccurredAtUtc), x.EventType, x.Actor, x.Version.ToString()); var proof = s.AddParagraph(); proof.Format.SpaceBefore = 12; proof.Format.Shading.Color = Color.Parse("#EAF4F2"); proof.AddFormattedText("KAYIT SNAPSHOT SHA-256\n", TextFormat.Bold); proof.AddText(snapshotHash); var footer = s.Footers.Primary.AddParagraph(); footer.Format.Alignment = ParagraphAlignment.Center; footer.AddText($"{r.RecordNumber} | Kontrollü elektronik kayıt | Sayfa "); footer.AddPageField(); footer.AddText(" / "); footer.AddNumPagesField(); var renderer = new PdfDocumentRenderer { Document = doc }; renderer.RenderDocument(); using var stream = new MemoryStream(); renderer.PdfDocument.Save(stream, false); return stream.ToArray(); }
    private static void Heading(Section s, string v) { var p = s.AddParagraph(v); p.Format.Font.Size = 13; p.Format.Font.Bold = true; p.Format.Font.Color = Color.Parse("#173C46"); p.Format.SpaceBefore = 10; p.Format.SpaceAfter = 5; }
    private static void Block(Section s, string label, string value) { var p = s.AddParagraph(); p.Format.SpaceAfter = 5; p.AddFormattedText(label + "\n", TextFormat.Bold); p.AddText(value); }
    private static void Grid(Section s, string[] v) { var t = Table(s, ["Alan", "Değer"]); for (var i = 0; i < v.Length; i += 2) Row(t, v[i], v[i + 1]); }
    private static Table Table(Section s, string[] h) { var t = s.AddTable(); t.Borders.Color = Color.Parse("#CBD9D7"); t.Borders.Width = .5; var width = 17.4 / h.Length; foreach (var _ in h) t.AddColumn(Unit.FromCentimeter(width)); var r = t.AddRow(); r.Shading.Color = Color.Parse("#EAF4F2"); for (var i = 0; i < h.Length; i++) Cell(r.Cells[i], h[i], true); return t; }
    private static void Row(Table t, params string[] v) { var r = t.AddRow(); for (var i = 0; i < v.Length; i++) Cell(r.Cells[i], v[i]); }
    private static void Cell(Cell c, string v, bool bold = false) { var p = c.AddParagraph(v); p.Format.Font.Bold = bold; p.Format.Font.Size = 8; c.VerticalAlignment = VerticalAlignment.Center; }
    private static string SnapshotHash(TrainingDetailsResponse d) => Convert.ToHexStringLower(SHA256.HashData(JsonSerializer.SerializeToUtf8Bytes(d))); private static string F(DateTimeOffset? v) => v?.ToOffset(TimeSpan.FromHours(3)).ToString("dd.MM.yyyy HH:mm 'TRT'") ?? "-"; private static void EnsureFont() { if (GlobalFontSettings.FontResolver is not null) return; lock (FontLock) GlobalFontSettings.FontResolver ??= new Resolver(); }
    private sealed class Resolver : IFontResolver { private static readonly string Regular = Path.Combine("/usr/share/fonts/truetype/dejavu", "DejaVuSans.ttf"); private static readonly string Bold = Path.Combine("/usr/share/fonts/truetype/dejavu", "DejaVuSans-Bold.ttf"); public byte[] GetFont(string f) => File.ReadAllBytes(f.EndsWith("Bold", StringComparison.Ordinal) ? Bold : Regular); public FontResolverInfo ResolveTypeface(string familyName, bool isBold, bool isItalic) => new(isBold ? "QmsBold" : "QmsRegular", false, false); }
}
